const raw = $json.body ?? $json;
const input = {
  session_id: raw.session_id || raw.input?.session_id || `manual_${Date.now()}`,
  story_prompt: raw.story_prompt || raw.input?.story_prompt || 'A frog named Jim cannot find love because he sings too loudly for the pond, until a quiet moth teaches him to listen to the night.',
  author_name: raw.author_name || raw.input?.author_name || 'Ghostwriter',
  mode: raw.mode || raw.input?.mode || 'public',
  requested_length_profile: raw.requested_length_profile || raw.input?.requested_length_profile || null,
  genre: raw.genre ?? raw.input?.genre ?? null,
  contract: raw.contract ?? raw.input?.contract ?? null,
  callback_url: raw.callback_url || raw.input?.callback_url || null,
  metadata: raw.metadata || raw.input?.metadata || {},
  constraints: raw.constraints || raw.input?.constraints || { content_rating: 'general', avoid: [] }
};
return [{ json: { input, telemetry_events: [], raw_input: raw } }];

const item = $input.first().json;
const events = item.telemetry_events || [];
events.push({
  event_id: `evt_${Date.now()}_${events.length + 1}`,
  session_id: item.input?.session_id || item.session_id || 'unknown',
  stage: 'accepted',
  status: 'complete',
  progress: 2,
  message: 'Request accepted and normalized.',
  timestamp: new Date().toISOString(),
  severity: 'info'
});
return [{ json: { ...item, telemetry_events: events } }];

const item = $input.first().json;
const input = item.input;
const errors = [];
if (!input.session_id || typeof input.session_id !== 'string') errors.push('session_id is required.');
if (!input.story_prompt || typeof input.story_prompt !== 'string' || input.story_prompt.trim().length < 10) errors.push('story_prompt must be at least 10 characters.');
if (input.story_prompt && input.story_prompt.length > 2000) errors.push('story_prompt must be 2,000 characters or fewer.');
if (!['public','internal'].includes(input.mode)) errors.push('mode must be public or internal.');
const events = item.telemetry_events || [];
events.push({event_id:`evt_${Date.now()}_${events.length+1}`, session_id:input.session_id || 'unknown', stage:'validate_input', status: errors.length ? 'failed' : 'complete', progress:5, message: errors.length ? 'Input validation failed.' : 'Input validated.', timestamp:new Date().toISOString(), severity: errors.length ? 'error' : 'info', details:{errors}});
return [{ json: { ...item, telemetry_events: events, input_valid: errors.length === 0, validation_errors: errors } }];

const item = $input.first().json;
const input = item.input || {};
const error = { stage:'validate_input', error_code:'INVALID_INPUT', message:(item.validation_errors || ['Invalid input.']).join(' '), retryable:true };
const failure_payload = { session_id: input.session_id || 'unknown', callback_type:'failure', status:'failed', error };
return [{ json: { ...item, workflow_failed:true, error, callback_payload: failure_payload, response: failure_payload } }];

const item = $input.first().json;
const stage = 'creative_interpretation';
const targetKey = 'creative_interpretation';
const required = ["session_id", "recommended_length_profile", "target_word_count", "selected_narrative_framework", "selected_act_structure"];
function extractText(obj) {
  return obj?.candidates?.[0]?.content?.parts?.[0]?.text ?? obj?.text ?? obj?.raw_text ?? obj?.output ?? '';
}
function clean(text) {
  return String(text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
}
let parsed = null;
let rawText = extractText(item);
try {
  parsed = JSON.parse(clean(rawText));
  const missing = required.filter(k => parsed[k] === undefined || parsed[k] === null);
  if (missing.length) throw new Error(`Missing required keys: ${missing.join(', ')}`);
  return [{ json: { ...item, [targetKey]: parsed, [`${stage}_raw`]: rawText, json_valid: true, workflow_failed: false } }];
} catch (error) {
  const events = item.telemetry_events || [];
  events.push({event_id:`evt_${Date.now()}_${events.length+1}`, session_id:item.input?.session_id || 'unknown', stage, status:'warning', progress:item.current_progress || 0, message:`${stage} returned invalid JSON.`, timestamp:new Date().toISOString(), severity:'warning', details:{error:error.message}});
  return [{ json: { ...item, telemetry_events: events, [`${stage}_raw`]: rawText, json_valid: false, workflow_failed: true, error: { stage, error_code:'INVALID_JSON', message:error.message, retryable:true } } }];
}

